import ee
from datetime import datetime, timedelta

ee.Initialize(project='earthsense-436113')

# 1) Geometry and date windows
geom = ee.Geometry.Rectangle([115.9, 28.4, 116.9, 29.95])
w1_start, w1_end = '2022-07-05', '2022-07-15'
w2_start, w2_end = '2022-08-22', '2022-08-31'

def widen(start_str, end_str, days=10):
    fmt = '%Y-%m-%d'
    s = datetime.strptime(start_str, fmt) - timedelta(days=days)
    e = datetime.strptime(end_str, fmt) + timedelta(days=days)
    return s.strftime(fmt), e.strftime(fmt)

# 2) Collection builders and masks
def mask_s2(img):
    scl = img.select('SCL')
    mask = scl.neq(1).And(scl.neq(2)).And(scl.neq(3)).And(scl.neq(8)).And(scl.neq(9)).And(scl.neq(10)).And(scl.neq(11))
    return img.updateMask(mask)

def prep_s2(img):
    img = mask_s2(img)
    return img.select(['B3','B8','B11'], ['green','nir','swir1'])

def build_s2(start, end):
    return (ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterBounds(geom)
            .filterDate(start, end)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
            .map(prep_s2))

def prep_ls(img):
    qa = img.select('QA_PIXEL')
    mask = (qa.bitwiseAnd(1<<1).eq(0)   # Dilated cloud
            .And(qa.bitwiseAnd(1<<2).eq(0))  # Cirrus
            .And(qa.bitwiseAnd(1<<3).eq(0))  # Cloud
            .And(qa.bitwiseAnd(1<<4).eq(0))) # Cloud shadow
    optical = img.select(['SR_B3','SR_B5','SR_B6']).multiply(0.0000275).add(-0.2)
    return optical.updateMask(mask).rename(['green','nir','swir1'])

def build_ls(start, end):
    l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(geom).filterDate(start, end).map(prep_ls)
    l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(geom).filterDate(start, end).map(prep_ls)
    return l8.merge(l9)

# 3) Processing per window
def process_window(start, end, label):
    try:
        col = build_s2(start, end)
        n = col.size().getInfo()
        src = 'S2'
        s2_start, s2_end = start, end
        if n == 0:
            s2_start, s2_end = widen(start, end, 10)
            col = build_s2(s2_start, s2_end)
            n = col.size().getInfo()
        if n == 0:
            col = build_ls(start, end); src = 'LS'; n = col.size().getInfo()
            if n == 0:
                ls_start, ls_end = widen(start, end, 10)
                col = build_ls(ls_start, ls_end); src = 'LSw'; n = col.size().getInfo()
                if n == 0:
                    print(f"{label} Images: 0")
                    return {'status':'C1'}
        mosaic = col.median().clip(geom)
        total = ee.Image(1).rename('ones').reduceRegion(reducer=ee.Reducer.count(), geometry=geom, scale=1000, maxPixels=1e9).get('ones').getInfo()
        valid = mosaic.select('green').reduceRegion(reducer=ee.Reducer.count(), geometry=geom, scale=1000, maxPixels=1e9).get('green').getInfo()
        if valid is None or valid == 0:
            print(f"{label} {src} Images: {n}, Valid: 0/{total} (cloud ~100%)")
            return {'status':'C2'}
        mndwi = mosaic.normalizedDifference(['green','swir1']).rename('mndwi')
        water = mndwi.gt(0.3)
        area_m2 = ee.Image.pixelArea().multiply(water.unmask(0)).reduceRegion(
            reducer=ee.Reducer.sum(), geometry=geom, scale=1000, maxPixels=1e9).get('area').getInfo()
        if area_m2 is None:
            print(f"{label} {src} Images: {n}, Calculation None")
            return {'status':'C3'}
        area_km2 = area_m2 / 1e6
        cloud_pct = 100.0 * (1.0 - (valid / float(total if total else 1)))
        print(f"{label} {src} Images: {n}, Valid: {valid}/{total} (cloud ~{cloud_pct:.1f}%), Water: {area_km2:.1f} km²")
        return {'status':'OK', 'area_km2': area_km2}
    except Exception as e:
        print(f"{label} Error: {str(e)[:80]}")
        return {'status':'D'}

# 4) Run both windows and decide
r1 = process_window(w1_start, w1_end, "Jul10±5d")
r2 = process_window(w2_start, w2_end, "Aug27±5d")

def final_tag(r1, r2):
    if r1['status'] == 'D' or r2['status'] == 'D':
        return "D"
    if r1['status'] == 'C1' or r2['status'] == 'C1':
        return "C1"
    if r1['status'] == 'C2' or r2['status'] == 'C2':
        return "C2"
    if r1['status'] == 'C3' or r2['status'] == 'C3':
        return "C3"
    a1, a2 = r1.get('area_km2'), r2.get('area_km2')
    if a1 is None or a2 is None:
        return "C3"
    return "A" if a2 < a1 else "B"

tag = final_tag(r1, r2)
print(tag)
